using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Runtime.Serialization.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace MaohaiziPet {
public static class ResidenceTests {
    static LivingReport report;
    static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Check(string name,Action run){var item=new TestResult{name=name};try{run();item.passed=true;report.passed++;}catch(Exception e){item.error=e.Message;report.failed++;}report.tests.Add(item);}
    static byte[] Pixels(BitmapSource image){byte[] data=new byte[image.PixelWidth*image.PixelHeight*4];image.CopyPixels(data,image.PixelWidth*4,0);return data;}
    static void Settle(PetController c){c.Habits.Interrupt();c.Skin.Motion.Cancel();for(int i=0;i<2000&&c.Skin.Motion.Active;i++){c.AdvanceMotions(.05);c.Pet.MoveForPlay(.05);}}
    static void Step(PetController c,double dt){c.UpdateNeeds(dt,12);c.UpdateWalkRoom();c.Habits.Tick(dt,PetMode.Companion,c.Skin.Motion.Recovering,false);c.AdvanceMotions(dt);c.Pet.MoveForPlay(dt);}
    static void Render(PetController c,double time,string path,double originX,double originY){var visual=new DrawingVisual();using(var d=visual.RenderOpen()){d.DrawRectangle(new SolidColorBrush(Color.FromRgb(243,242,238)),null,new Rect(0,0,840,480));var r=c.Pet.Surface.PetRect;r.Offset(c.Pet.Left-originX,c.Pet.Top-originY);c.Skin.Draw(d,0,time,r);d.DrawText(new FormattedText("软件行为模拟 · 全程未操作鼠标",System.Globalization.CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei"),15,Brushes.DimGray),new Point(24,22));d.DrawText(new FormattedText(TimeSpan.FromSeconds(time).ToString(@"mm\:ss")+"  "+c.Habits.Phase+(c.Skin.Motion.PostureActivity==null?"":" · 自主观察 / 调整姿势"),System.Globalization.CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei"),14,Brushes.DimGray),new Point(24,445));}var target=new RenderTargetBitmap(840,480,96,96,PixelFormats.Pbgra32);target.Render(visual);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(target));using(var file=File.Create(path))png.Save(file);}
    public static int Preview(string manifest,string output,bool standingPreview=false){
        Directory.CreateDirectory(output);PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-preview-state"));var app=new Application();var c=new PetController(app);c.Skin=PetSkin.Load(manifest);c.ConfigureMotions();c.Settings.Mode=PetMode.Companion;c.Engine.SetMode(PetMode.Companion);c.Settings.Size=200;c.Pet=new PetWindow(c);c.Pet.Surface.Measure(new Size(c.Pet.Width,c.Pet.Height));c.Pet.Surface.Arrange(new Rect(0,0,c.Pet.Width,c.Pet.Height));var area=SystemParameters.WorkArea;c.Pet.Left=area.Left+(area.Width-c.Pet.Width)/2;c.Pet.Top=area.Top+(area.Height-c.Pet.Height)/2;double originX=c.Pet.Left-180,originY=c.Pet.Top-50;string frames=Path.Combine(output,"frames");Directory.CreateDirectory(frames);var timeline=new List<string>();
        if(standingPreview){c.StartHabit(CatHabit.StandUp);c.AdvanceMotions(0);}
        for(int frame=0;frame<(standingPreview?240:1080);frame++){for(int sub=0;sub<5;sub++)Step(c,1.0/60);double time=(frame+1)/12.0;Render(c,time,Path.Combine(frames,"frame-"+frame.ToString("D5")+".png"),originX,originY);if(frame%120==0){Console.WriteLine("Autonomous preview: "+(int)time+" seconds");timeline.Add(((int)time)+"s: "+c.Habits.Current+" / "+c.Skin.Motion.PostureActivity);}}
        File.WriteAllLines(Path.Combine(output,"timeline.txt"),timeline);Settle(c);c.Pet.Close();c.Dispose();return 0;
    }
    public static int Run(string manifest,string output){
        Directory.CreateDirectory(output);PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-state"));report=new LivingReport{scope="Persistent pose residence, native in-pose activities, seamless stand/walk handoffs and unattended time budgets"};
        var app=new Application();var c=new PetController(app);c.Skin=PetSkin.Load(manifest);c.ConfigureMotions();c.Settings.Mode=PetMode.Companion;c.Engine.SetMode(PetMode.Companion);c.Settings.Size=180;c.Pet=new PetWindow(c);c.Pet.Surface.Measure(new Size(c.Pet.Width,c.Pet.Height));c.Pet.Surface.Arrange(new Rect(0,0,c.Pet.Width,c.Pet.Height));var area=SystemParameters.WorkArea;c.Pet.Left=area.Left+(area.Width-c.Pet.Width)/2;c.Pet.Top=area.Top+(area.Height-c.Pet.Height)/2;
        Check("姿态是有实际停留的状态，不再把整段动作拉慢",delegate{foreach(var pair in new[]{new KeyValuePair<CatHabit,string>(CatHabit.SitUp,"sit"),new KeyValuePair<CatHabit,string>(CatHabit.StandUp,"stand"),new KeyValuePair<CatHabit,string>(CatHabit.CurlSleep,"sleep")}){var clip=c.Skin.Motions.Clips[pair.Value];var h=new CatHabits(71){SitReady=true,StandReady=true,SleepReady=true};h.SetResidenceTiming(pair.Key,clip.Spec.holdAt/clip.Spec.fps,clip.Spec.frames/clip.Spec.fps);Assert(h.Start(pair.Key,PetMode.Companion,false),"状态未发起");double minimum=pair.Key==CatHabit.SitUp?24:pair.Key==CatHabit.StandUp?14:28;Assert(h.DwellSeconds>=minimum,"实际停留过短");Assert(Math.Abs(h.Duration-(clip.Spec.frames/clip.Spec.fps+h.DwellSeconds))<.001,"通过慢放进入收尾伪造停留");}});
        Check("长时间停留只改变这一次驻留，源素材和播放速度保持一致",delegate{var clip=c.Skin.Motions.Clips["sit"];double saved=clip.Spec.holdSeconds;var p=new MotionPlayer();p.StartResidence(clip,40);p.Tick(clip.Spec.holdAt/clip.Spec.fps);Assert(p.HoldingPose&&p.FrameIndex==clip.Spec.holdAt,"进入速度改变");p.Tick(20);Assert(p.HoldingPose&&p.FrameIndex==clip.Spec.holdAt,"没有持续坐着");Assert(clip.Spec.holdSeconds==saved,"修改了共享素材参数");p.Cancel();for(int i=0;i<400&&p.Active;i++)p.Tick(.05);Assert(!p.Active,"长驻留无法自然结束");});
        Check("常驻站姿保留侧身全长和完整尾巴，脸部命中跟随新姿态",delegate{var clip=c.Skin.Motions.Clips["stand"];var frame=clip.Frames[clip.Spec.holdAt];byte[] px=Pixels(frame);int left=frame.PixelWidth,right=0;for(int y=0;y<frame.PixelHeight;y++)for(int x=0;x<frame.PixelWidth;x++)if(px[(y*frame.PixelWidth+x)*4+3]>=230){left=Math.Min(left,x);right=Math.Max(right,x);}Assert(right-left>280,"站立停留仍然是狭窄的正面对称姿势");var p=new MotionPlayer();p.StartResidence(clip,30);p.Tick(clip.Spec.holdAt/clip.Spec.fps);Assert(p.HoldingPose&&p.TouchNose.X<40&&p.TouchNose.Y<80,"脸部互动仍指向旧正面站姿");});
        Check("坐姿和站姿各有不同的原生小活动，锚点完全对应当前姿态",delegate{foreach(string pose in new[]{"sit","stand"}){var parent=c.Skin.Motions.Clips[pose];var children=c.Skin.Motions.Clips.Values.Where(x=>x.Spec.parentPose==pose).ToArray();Assert(children.Length>=2,"缺少姿态内活动："+pose);foreach(var child in children){Assert(child.Spec.physicalTransitionReviewed&&child.Spec.transitionSource=="continuous-video","小活动不是复核后的连续素材");Assert(MotionLibrary.SamePose(child.Frames[0],parent.Frames[parent.Spec.holdAt])&&MotionLibrary.SamePose(child.Frames.Last(),parent.Frames[parent.Spec.holdAt]),"活动后换成另一只猫或回到趴姿");}}});
        Check("姿态内活动全程无人操作也会出现，且不连续重复同一段",delegate{foreach(string pose in new[]{"sit","stand"}){var children=c.Skin.Motions.Clips.Values.Where(x=>x.Spec.parentPose==pose).ToArray();Assert(children.Length>=2,"活动素材不足");var life=new PoseLife(children,29);string previous=null;bool active=false;var seen=new HashSet<string>();for(int i=0;i<2400;i++){life.Tick(.05,200-i*.05);if(life.Active&&!active){Assert(life.Clip.Spec.id!=previous,"重复同一段活动");previous=life.Clip.Spec.id;seen.Add(previous);}active=life.Active;}Assert(life.ActivityCount>=6&&seen.Count>=2,"保持姿态时长期无事发生");}});
        Check("抚摸打断姿态内动作时先完成小活动，再自然退出当前姿态",delegate{var clip=c.Skin.Motions.Clips["sit"];var p=new MotionPlayer();p.ConfigureLibrary(c.Skin.Motions);p.StartResidence(clip,40);for(int i=0;i<1000&&p.PostureActivity==null;i++)p.Tick(.02);Assert(p.PostureActivity!=null,"没有自主小活动");int at=p.FrameIndex;p.Cancel();p.Tick(.01);Assert(p.Active&&p.Recovering&&p.FrameIndex==at,"打断小活动时硬切身体");for(int i=0;i<2000&&p.Active;i++)p.Tick(.02);Assert(!p.Active,"打断后停不下来");});
        Check("摸持续坐姿时在原姿势回应，不强制趴下再起身",delegate{Settle(c);c.StartHabit(CatHabit.SitUp);c.AdvanceMotions(0);for(int i=0;i<1000&&!c.Skin.Motion.HoldingPose;i++)Step(c,.02);Assert(c.Skin.Motion.HoldingPose,"没有进入坐姿");c.Touch(PetTouchZone.Head,true,0);for(int i=0;i<250;i++){Step(c,.02);Assert(c.Habits.Current==CatHabit.SitUp&&c.Skin.Motion.HoldingPose&&c.Skin.Motion.Clip.Spec.id=="sit"&&!c.Skin.Motion.Recovering,"抚摸把坐姿重置成趴姿");}Assert(c.Skin.Motion.PostureActivityCount>0&&!c.Companion.Touch.Active,"没有姿态内回应，或错误启动中立纹理的形变");});
        Check("走完后直接保持站立，站着继续迈步也不重新趴下起身",delegate{foreach(string id in new[]{"walk-left","walk-right"}){Settle(c);var clip=c.Skin.Motions.Clips[id];var player=c.Skin.Motion;player.StartLivingWalk(clip,clip.Seconds);for(int i=0;i<3000&&!player.AtStandingExit;i++)player.Tick(1.0/60);Assert(player.AtStandingExit,"未到站姿接点");int standingSize=c.Skin.Motions.Clips["stand"].Size;byte[] before=Pixels(new CroppedBitmap(player.Image,new Int32Rect((clip.Size-standingSize)/2,(clip.Size-standingSize)/2,standingSize,standingSize)));player.ContinueStanding(24);Assert(player.HoldingPose&&player.Clip.Spec.id=="stand"&&Pixels(player.Image).SequenceEqual(before),"走动到站姿发生画面跳变");Assert(player.CanEnterWalk(clip),"站姿不能直接继续迈步");player.EnterWalk(clip,clip.Seconds);Assert(player.Clip.Spec.id==id&&player.FrameIndex==clip.Spec.standEntryAt&&Pixels(new CroppedBitmap(player.Image,new Int32Rect((clip.Size-standingSize)/2,(clip.Size-standingSize)/2,standingSize,standingSize))).SequenceEqual(before),"从站姿重新回到趴姿起身");}});
        Check("坐站切换复用同一段原生起身过程，不经过默认趴姿",delegate{Settle(c);var sitting=c.Skin.Motions.Clips["sit"];var standing=c.Skin.Motions.Clips["stand"];var p=new MotionPlayer();p.ConfigureLibrary(c.Skin.Motions);p.StartResidence(sitting,30);p.Tick(sitting.Spec.holdAt/sitting.Spec.fps);Assert(p.CanEnterStanding(standing),"坐姿没有直接起身接点");byte[] before=Pixels(p.Image);p.EnterStanding(standing,24);Assert(p.FrameIndex==standing.Spec.sitEntryAt&&MotionLibrary.SamePose(p.Image,sitting.Frames[sitting.Spec.holdAt]),"起身接点不是同一只猫同一姿势");for(int i=0;i<600&&!p.HoldingPose;i++){p.Tick(.01);Assert(p.FrameIndex>=standing.Spec.sitEntryAt,"坐站切换倒退回趴姿");}Assert(p.HoldingPose&&p.Clip.Spec.id=="stand","没有保持站着");p.EnterSitting(sitting,30);for(int i=0;i<600&&p.Clip.Spec.id!="sit";i++)p.Tick(.01);Assert(p.Clip.Spec.id=="sit"&&p.HoldingPose&&p.FrameIndex==sitting.Spec.holdAt&&Pixels(p.Image).SequenceEqual(before),"站回坐姿没有接回原坐姿");});
        Check("自然站姿和转身使用完整画布，尾巴透明命中不被默认画布裁掉",delegate{Settle(c);var player=c.Skin.Motion;var standing=c.Skin.Motions.Clips["stand"];player.StartResidence(standing,40);for(int i=0;i<2000&&player.PostureActivity!="stand-look";i++)player.Tick(.02);Assert(player.PostureActivity=="stand-look","没有转身观察");Assert(player.VisualSize>=standing.Size&&standing.Size==416,"仍用父姿态画布缩放整个身体");bool found=false;for(int sample=0;sample<123&&player.PostureActivity=="stand-look"&&!found;sample++){byte[] pixels=Pixels(player.Image);for(int y=0;y<player.VisualSize&&!found;y++)for(int x=0;x<player.VisualSize&&!found;x++){double logicalX=x+player.VisualSpec.originX,logicalY=y+player.VisualSpec.originY;if(logicalX<=256||pixels[(y*player.VisualSize+x)*4+3]<230)continue;var r=c.Pet.Surface.PetRect;var point=new Point(r.X+(logicalX+.5)*r.Width/256,r.Y+(logicalY+.5)*r.Height/256);Assert(c.Pet.Surface.HitBody(point),"父姿态边界挡住了真实尾巴");found=true;}player.Tick(1.0/24);}Assert(found,"没有检测到需要扩展命中的实际身体部位");});
        Check("十分钟无人操作主要保持多种生活姿态，且确实会走到别处",delegate{Settle(c);double held=0,loaf=0,small=0,minX=c.Pet.Left,maxX=c.Pet.Left;var poses=new HashSet<string>();int changed=0;string previous=null;for(int i=0;i<12000;i++){Step(c,.05);if(c.Skin.Motion.HoldingPose){held+=.05;poses.Add(c.Skin.Motion.Clip.Spec.id);}if(!c.Skin.Motion.Active)loaf+=.05;if(c.Skin.Motion.PostureActivity!=null)small+=.05;minX=Math.Min(minX,c.Pet.Left);maxX=Math.Max(maxX,c.Pet.Left);string now=c.Skin.Motion.Active?c.Skin.Motion.Clip.Spec.id:"loaf";if(now!=previous){changed++;previous=now;}}Assert(held/600>=.60,"大部分时间仍然回到同一个趴姿："+held);Assert(loaf/600<.18,"长时间停在默认趴姿："+loaf);Assert(poses.Contains("sit")&&poses.Contains("stand")&&poses.Contains("sleep"),"常驻姿态缺失");Assert(small>20,"持有姿态时没有足够的自主活动");Assert(maxX-minX>15,"没有实际换位置");File.WriteAllText(Path.Combine(output,"unattended-budget.json"),"{\"seconds\":600,\"persistent_pose_seconds\":"+held.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"neutral_loaf_seconds\":"+loaf.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"native_in_pose_activity_seconds\":"+small.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"world_x_span\":"+(maxX-minX).ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"state_changes\":"+changed+"}");});
        Settle(c);c.Pet.Close();c.Dispose();using(var file=File.Create(Path.Combine(output,"residence-test-report.json")))new DataContractJsonSerializer(typeof(LivingReport)).WriteObject(file,report);return report.failed==0?0:1;
    }
}
}
